 p=material.get('pbrMetallicRoughness',{});v={'baseColorFactor':p.get('baseColorFactor',[1.,1.,1.,1.]),'roughnessFactor':p.get('roughnessFactor',1.),'metallicFactor':p.get('metallicFactor',1.)}
